'use strict';
const KEY='nutrix-care-prototype-v1';
const cloud=CareCloud;
const emptyState=()=>({version:1,operator:'',animals:[],tasks:[],events:[]});
let storageReadError=false;
let state;
try{const saved=localStorage.getItem(KEY);state=saved?JSON.parse(saved):Care.seed();if(state.version!==1||!Array.isArray(state.animals)||!Array.isArray(state.tasks)||!Array.isArray(state.events))throw Error('รูปแบบข้อมูลไม่ถูกต้อง');}catch(e){state=Care.seed();storageReadError=true;}
if(cloud.enabled){state=emptyState();storageReadError=false;}
let view='map',selectedMonth=Care.bangkokDate().slice(0,7),query='',statusFilter='ทั้งหมด',toastTimer;
const dialog=document.getElementById('dialog');
const $=s=>document.querySelector(s);
const esc=v=>String(v??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const statuses=['ยังไม่ประเมิน','ปกติ','เฝ้าระวัง','อยู่ระหว่างดูแลรักษา','แยกดูแล'];
const navs=[['map','ผังคอก','grid'],['animals','สัตว์ในศูนย์','paw'],['tasks','งานดูแล','check'],['monthly','ตรวจรายเดือน','calendar'],['history','บันทึก','clock']];
const paths={grid:'M3 3h7v7H3z M14 3h7v7h-7z M3 14h7v7H3z M14 14h7v7h-7z',paw:'M8 14c-3 3-3 6 0 6 2 0 2-1 4-1s2 1 4 1c3 0 3-3 0-6-2-3-6-3-8 0Z M5 8a2 3 0 1 0 0 .1 M10 4a2 3 0 1 0 0 .1 M16 4a2 3 0 1 0 0 .1 M21 8a2 3 0 1 0 0 .1',check:'M9 5H5v16h14V5h-4 M9 3h6v4H9z M8 14l3 3 5-6',calendar:'M4 5h16v16H4z M4 10h16 M8 3v4 M16 3v4 M8 14h2 M14 14h2 M8 18h2',clock:'M12 3a9 9 0 1 0 0 18 9 9 0 1 0 0-18 M12 7v5l3 2',plus:'M12 5v14 M5 12h14',arrow:'M5 12h14 M14 7l5 5-5 5',heart:'M12 20 4 12C-2 6 7-1 12 6 17-1 26 6 20 12Z',home:'M3 10 12 3l9 7 M5 9v12h14V9 M9 21v-7h6v7',download:'M12 3v12 M7 10l5 5 5-5 M4 17v4h16v-4'};
const icon=name=>`<svg viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="1.6" stroke-linecap="round" stroke-linejoin="round" aria-hidden="true"><path d="${paths[name]||paths.grid}"/></svg>`;
const findAnimal=id=>state.animals.find(a=>a.id===id);
const occupants=code=>state.animals.filter(a=>a.kennel===code);
const currentMonth=()=>Care.bangkokDate().slice(0,7);
const latestCheck=(a,month)=>[...a.checks].reverse().find(c=>c.month===month);
const monthlyProblems=(animals,month)=>animals.filter(a=>Care.hasMonthlyIssue(latestCheck(a,month)));
const healthClass=s=>['เฝ้าระวัง','อยู่ระหว่างดูแลรักษา'].includes(s)?'amber':s==='แยกดูแล'?'red':s==='ปกติ'?'':'neutral';
const tag=(text,cls='')=>`<span class="tag ${cls}">${esc(text)}</span>`;
function thaiDate(value,withTime=false){if(!value)return '—';const d=new Date(value.length===10?value+'T12:00:00+07:00':value);if(isNaN(d))return '—';return new Intl.DateTimeFormat('th-TH',{timeZone:'Asia/Bangkok',day:'numeric',month:'short',year:'numeric',...(withTime?{hour:'2-digit',minute:'2-digit'}:{})}).format(d);}
function thaiMonth(v){return new Intl.DateTimeFormat('th-TH',{timeZone:'Asia/Bangkok',month:'long',year:'numeric'}).format(new Date(v+'-01T12:00:00+07:00'));}
function toast(msg){$('#toast').textContent=msg;$('#toast').classList.add('show');clearTimeout(toastTimer);toastTimer=setTimeout(()=>$('#toast').classList.remove('show'),3500);}
function addEvent(draft,text,operator){draft.events.unshift({id:crypto.randomUUID(),text,operator,time:new Date().toISOString()});}
async function commit(draft){
 if(cloud.enabled){const saved=await cloud.write(draft);state=saved;render();return;}
 if(storageReadError)throw Error('อ่านข้อมูลเดิมไม่ได้ จึงหยุดการเขียนทับ');
 try{localStorage.setItem(KEY,JSON.stringify(draft));}catch(e){throw Error('บันทึกในเครื่องไม่ได้');}state=draft;render();
}
function heading(eyebrow,title,subtitle,action=''){return `<div class="page-heading"><div><h1>${title}</h1><p class="subtitle">${subtitle}</p></div>${action}</div>`;}
function addButton(kennel=''){return `<button class="primary" data-action="add-animal" data-kennel="${esc(kennel)}">${icon('plus')} เพิ่มสัตว์</button>`;}
function render(){
 if(cloud.enabled&&!cloud.ready){renderCloudLogin();return;}
  const nav=navs.map(([id,label,i])=>`<a href="#${id}" class="nav-item ${view===id?'active':''}" ${view===id?'aria-current="page"':''}>${icon(i)}<span>${label}</span></a>`).join('');
  $('#desktop-nav').innerHTML=nav;$('#mobile-nav').innerHTML=nav;$('#page-name').textContent=navs.find(n=>n[0]===view)?.[1]||'ผังคอก';$('#operator-label').textContent=cloud.enabled?cloud.member.name:state.operator||'ตั้งชื่อผู้บันทึก';
  $('#main').innerHTML=({map:renderMap,animals:renderAnimals,tasks:renderTasks,monthly:renderMonthly,history:renderHistory}[view]||renderMap)();
  const legacyAnimals=state.animals.filter(a=>!Care.kennels.includes(a.kennel));
  if(legacyAnimals.length)$('#main').insertAdjacentHTML('afterbegin',`<div class="notice">มีสัตว์ ${legacyAnimals.length} ตัวอยู่ในรหัสกรงเดิมที่ไม่อยู่ในผังใหม่ ข้อมูลและประวัติยังอยู่ครบ กรุณาเปิดทะเบียนสัตว์เพื่อย้ายไปกรงที่ถูกต้อง: ${legacyAnimals.map(a=>esc(a.name)+' ('+esc(a.kennel)+')').join(', ')} <a class="text-link" href="#animals">เปิดทะเบียนสัตว์ →</a></div>`);
  if(storageReadError)$('#main').insertAdjacentHTML('afterbegin','<div class="error">อ่านข้อมูลที่เก็บไว้ไม่ได้ ขณะนี้แสดงตัวอย่างและระงับการบันทึกเพื่อป้องกันข้อมูลเดิมถูกเขียนทับ</div>');
}
function renderStats(){const animals=state.animals.filter(a=>a.kennel.startsWith(`D${SitePlan.selectedBuilding}-`));const capacity=Care.kennelsFor(SitePlan.selectedBuilding).length;const used=new Set(animals.filter(a=>Care.kennels.includes(a.kennel)).map(a=>a.kennel)).size;const watch=animals.filter(a=>!['ปกติ','ยังไม่ประเมิน'].includes(a.status)).length;return `<div class="stats">${[[animals.length,'สัตว์ในอาคาร','ตัว','paw',`ข้อมูลในอาคาร ${SitePlan.selectedBuilding}`],[capacity-used,'กรงว่าง','กรง','home',`${used} จาก ${capacity} กรงมีสัตว์`],[watch,'ต้องติดตาม','ตัว','heart','ตามสถานะสุขภาพที่บันทึก'],[monthlyProblems(animals,currentMonth()).length,'พบปัญหาเดือนนี้','ตัว','calendar',thaiMonth(currentMonth())]].map(([v,t,u,i,n],idx)=>`<div class="stat"><div><div class="stat-title">${t}</div><div class="stat-value">${v}<small>${u}</small></div><div class="stat-note">${n}</div></div><span class="stat-icon ${idx===2?'amber':''}">${icon(i)}</span></div>`).join('')}</div>`;}
function renderMap(){return SitePlan.level==='overview'?SitePlan.render():`<div class="plan-back"><button class="secondary" data-plan="overview">← กลับผังพื้นที่สีเขียว</button><span>ผังศูนย์ / อาคารสุนัข ${SitePlan.selectedBuilding}</span></div>`+renderBuildingMap();}
function renderBuildingMap(){
 const building=SitePlan.selectedBuilding,layout=Care.layoutFor(building),capacity=Care.kennelsFor(building).length,animals=state.animals.filter(a=>a.kennel.startsWith(`D${building}-`));
 const row=r=>Array.from({length:layout.counts[r]},(_,i)=>{const code=`D${building}-${r}${String(i+1).padStart(2,'0')}`,as=occupants(code),watch=as.some(a=>!['ปกติ','ยังไม่ประเมิน'].includes(a.status));return `<button class="kennel ${as.length?'occupied':''} ${watch?'watch':''}" data-action="kennel" data-code="${code}" aria-label="${code} ${as.length?as.map(a=>esc(a.name)).join(', '):'กรงว่าง'}"><div class="kennel-code">${r}${String(i+1).padStart(2,'0')}<span class="dot ${as.length?(watch?'amber':'green'):''}"></span></div>${as.length?`<div class="kennel-name">${esc(as[0].name)}${as.length>1?` +${as.length-1}`:''}</div><div class="kennel-small">${as.length} ตัว ${as.some(a=>a.placementExample)?'• ตำแหน่งตัวอย่าง':''}</div>`:'<div class="kennel-empty">กรงว่าง ＋</div>'}</button>`;}).join('');
 const kennelLayout=`<div class="kennel-aisle-grid ${layout.rows.length===1?'single-row':''}">${layout.rows.map((r,index)=>`${index?'<div class="kennel-aisle" aria-label="ทางเดินกลางอาคาร"><span>ทางเดินกลางอาคาร ↓</span></div>':''}<section class="kennel-row" aria-label="กรงแถว ${r}"><div class="building-label"><strong>${building===5?'คอกคลินิก · แถวเดียว':'แถว '+r}</strong><span>${r}01 ↓ ${r}${layout.counts[r]}</span></div><div class="map-grid">${row(r)}</div></section>`).join('')}</div>`;
 const sunny=animals[0],issueCount=monthlyProblems(animals,currentMonth()).length;
 return `<div class="page-heading" style="justify-content:flex-end">${addButton(`D${building}-A01`)}</div>`+renderStats()+`<div class="content-grid"><section class="card"><div class="card-head"><div><h2>ผังคอก · อาคารสุนัข ${building}${building===5?' (คอกคลินิก)':''}</h2><p>${layout.rows.map(r=>`แถว ${r} ${layout.counts[r]} กรง`).join(' · ')} · รองรับหลายตัวต่อกรง</p></div>${tag(capacity+' กรง')}</div><div class="toolbar"><div class="legend"><span><i class="dot"></i>กรงว่าง</span><span><i class="dot green"></i>มีสัตว์</span><span><i class="dot amber"></i>มีสัตว์ต้องติดตาม</span></div><span class="mobile-date">${thaiDate(Care.bangkokDate())}</span></div><div class="map-body">${kennelLayout}<p class="map-foot">ⓘ เลื่อนลงเพื่อดูกรงทั้งหมด • ทิศทางนับกรงรอยืนยันหน้างาน</p></div></section><aside class="side-column"><section class="card side-card panel-pad"><div class="side-title">${icon('paw')}<h3>ประวัติย่อ</h3></div>${sunny?`<div class="feature-animal"><div class="avatar">${esc(sunny.name.slice(0,1))}</div><div><div class="animal-name">${esc(sunny.name)}</div><div class="animal-id">${esc(Care.animalCode(sunny)||'ไม่ระบุรหัส')}</div></div></div><div class="profile-meta">${tag(sunny.stage||'ไม่ระบุช่วงวัย','neutral')}${tag(sunny.status,healthClass(sunny.status))}</div><p class="side-copy">${esc(sunny.breed)} · ${esc(sunny.kennel)}<br>${Care.age(sunny.birth)}</p><button class="secondary full" data-action="profile" data-id="${esc(sunny.id)}">เปิดประวัติ ${icon('arrow')}</button>`:'<p class="empty-small">เพิ่มสัตว์ตัวแรกเพื่อเริ่มดูแล</p>'}</section><section class="card side-card panel-pad"><div class="side-title">${icon('calendar')}<h3>สุขอนามัยรายเดือน</h3></div><p class="side-copy">ตรวจสภาพขน ความยาวเล็บ และความสะอาดหู</p><div class="count-line"><span>พบปัญหาเดือนนี้ ${issueCount} ตัว</span></div><p class="side-copy">เลือกสัตว์จากกรง แล้วบันทึกเฉพาะตัวที่พบปัญหา</p><a href="#monthly" class="text-link">เปิดรายการตรวจ ${icon('arrow')}</a></section><section class="card side-card panel-pad"><h3>ความเคลื่อนไหวล่าสุด</h3>${state.events.length?state.events.slice(0,3).map(eventHTML).join(''):'<p class="empty-small">เมื่อเพิ่มสัตว์ ย้ายคอก หรือบันทึกการดูแล ประวัติจะแสดงที่นี่</p>'}<a href="#history" class="text-link">ดูบันทึกทั้งหมด →</a></section></aside></div>`;
}
function animalRow(a){return `<button class="animal-row" data-action="profile" data-id="${esc(a.id)}"><div class="avatar">${esc(a.name.slice(0,1))}</div><div class="row-main"><div class="animal-name">${esc(a.name)}</div><div class="row-sub">${esc(Care.animalCode(a)||'ไม่ระบุรหัส')} · ${esc(a.breed)} · ${esc(a.kennel)}</div></div>${tag(a.status,healthClass(a.status))}<span class="arrow">›</span></button>`;}
function renderAnimals(){const as=state.animals.filter(a=>(a.name+' '+Care.animalCode(a)+' '+a.kennel).toLowerCase().includes(query.toLowerCase())&&(statusFilter==='ทั้งหมด'||a.status===statusFilter));return heading('EVERY ANIMAL HAS A STORY','สัตว์ในศูนย์','ทะเบียนสัตว์สำหรับอาคารสุนัข 1–6 รวมคอกคลินิก',addButton())+`<div class="search"><input id="animal-search" type="search" placeholder="ค้นหาชื่อ รหัสสัตว์ หรือรหัสคอก" aria-label="ค้นหาสัตว์" value="${esc(query)}"><select id="status-filter" aria-label="กรองสถานะสุขภาพ" style="max-width:230px">${['ทั้งหมด',...statuses].map(s=>`<option ${s===statusFilter?'selected':''}>${esc(s)}</option>`).join('')}</select></div><div class="list">${as.map(animalRow).join('')||'<div class="card empty-state">ไม่พบสัตว์ที่ตรงกับการค้นหา</div>'}</div>`;}
function renderTasks(){const pending=state.tasks.filter(t=>!t.done),done=state.tasks.filter(t=>t.done);const taskHTML=t=>`<div class="task ${t.done?'done':''}"><button class="done-btn" data-action="toggle-task" data-id="${esc(t.id)}" aria-label="${t.done?'เปิดงานอีกครั้ง':'ทำงานเสร็จ'}">${t.done?'✓':'○'}</button><div class="row-main"><h3>${esc(t.title)}</h3><div class="row-sub">${esc(findAnimal(t.animalId)?.name||t.animalId)} · ${thaiDate(t.due)} · ${esc(t.assignee||'ยังไม่มอบหมาย')}</div>${t.done?`<div class="row-sub">เสร็จโดย ${esc(t.completedBy)} · ${thaiDate(t.completedAt,true)}</div>`:''}</div>${!t.done&&t.due<Care.bangkokDate()?tag('เลยกำหนด','amber'):''}</div>`;return heading('CARE, ONE TASK AT A TIME','งานดูแล','งานที่ต้องทำ เวลา และผู้รับผิดชอบ',`<button class="primary" data-action="add-task">${icon('plus')} เพิ่มงาน</button>`)+`<div class="notice">รายการยาคือข้อมูลประกอบการดูแล หากต้องติดตามว่าให้ยาครั้งใดแล้ว ให้เพิ่มงานแยกพร้อมเวลาในรายละเอียด</div><div class="section-title"><h2>งานค้าง ${pending.length} งาน</h2></div><section class="card">${pending.sort((a,b)=>a.due.localeCompare(b.due)).map(taskHTML).join('')||'<div class="empty-state"><h3>ยังไม่มีงานค้าง</h3>เพิ่มงานจากหน้านี้หรือจากประวัติสัตว์ได้</div>'}</section>${done.length?`<div class="section-title"><h2>ทำเสร็จแล้ว ${done.length} งาน</h2></div><section class="card">${done.map(taskHTML).join('')}</section>`:''}`;}
function renderMonthly(){
 const issues=monthlyProblems(state.animals,selectedMonth);
 const resolved=state.animals.filter(a=>a.checks.some(c=>c.month===selectedMonth&&Care.hasMonthlyIssue(c))&&latestCheck(a,selectedMonth)&&!Care.hasMonthlyIssue(latestCheck(a,selectedMonth)));
 const item=(a,closed=false)=>{const c=latestCheck(a,selectedMonth);return `<div class="monthly-item"><div class="avatar">${esc(a.name.slice(0,1))}</div><div class="row-main"><h3>${esc(a.name)}</h3><div class="row-sub">${esc(Care.animalCode(a)||'ไม่ระบุรหัส')} · ${esc(a.kennel)}</div><div class="row-sub">${esc(c.operator)} · ${thaiDate(c.time,true)}</div></div>${tag(closed?'ติดตามแล้ว ไม่พบปัญหา':'พบปัญหา',closed?'':'amber')}<div class="checks">${[['ขน',c.coat],['เล็บ',c.nails],['หู',c.ears]].map(([label,value])=>`<span class="check-label">${label}: ${esc(value)}</span>`).join('')}</div>${c.note?`<p class="side-copy monthly-note">${esc(c.note)}</p>`:''}<button class="secondary" data-action="monthly-check" data-id="${esc(a.id)}" data-month="${selectedMonth}">บันทึกติดตาม</button><button class="text-link" data-action="profile" data-id="${esc(a.id)}">ประวัติ</button></div>`;};
 return heading('','ปัญหาสุขอนามัยรายเดือน','บันทึกเฉพาะตัวที่พบปัญหาขน เล็บ หรือหู',`<a href="#map" class="primary" data-plan="overview">เลือกสัตว์จากผังคอก</a>`)+`<div class="notice">เลือกอาคาร → กรง → สัตว์ → บันทึกปัญหาขน เล็บ หู • ตัวที่ไม่มีบันทึกไม่ได้หมายถึงตรวจแล้วหรือปกติ</div><div class="section-title"><div><h2>${thaiMonth(selectedMonth)}</h2><p class="subtitle">พบปัญหาที่ต้องติดตาม ${issues.length} ตัว · ปิดรายการแล้ว ${resolved.length} ตัว</p></div><label class="month-control"><input type="month" id="check-month" value="${selectedMonth}" max="${currentMonth()}" aria-label="เดือนที่ตรวจ"></label></div><section class="card">${issues.map(a=>item(a)).join('')||'<div class="empty-state"><h3>ไม่มีปัญหาที่เปิดติดตามในเดือนนี้</h3>บันทึกจากผังคอกเมื่อพบปัญหา</div>'}</section>${resolved.length?`<details class="section-title-resolved"><summary>รายการติดตามแล้ว ไม่พบปัญหา (${resolved.length} ตัว)</summary><section class="card">${resolved.map(a=>item(a,true)).join('')}</section></details>`:''}`;
}
function eventHTML(e){return `<div class="event"><span class="event-bullet"></span><div><p>${esc(e.text)}</p><small>${esc(e.operator)} · ${thaiDate(e.time,true)}</small></div></div>`;}
function renderHistory(){return heading('A CLEAR RECORD OF CARE','บันทึกการดูแล','ประวัติการเพิ่มสัตว์ ย้ายคอก และอัปเดตข้อมูล พร้อมชื่อผู้บันทึก')+`<div class="notice">${cloud.enabled?'ข้อมูลใหม่ผูกกับบัญชีผู้บันทึกในฐานข้อมูล ส่วนประวัตินำเข้าคงชื่อเดิมไว้':'ชื่อผู้บันทึกในต้นแบบเป็นชื่อที่กรอกเอง ยังไม่ได้ยืนยันตัวตนด้วยบัญชีผู้ใช้'}</div><section class="card panel-pad">${state.events.map(eventHTML).join('')||'<div class="empty-state"><h3>เริ่มบันทึกเมื่อคุณพร้อม</h3>กิจกรรมที่บันทึกจะปรากฏที่นี่</div>'}</section>`;}
function openModal(title,body,actions='',subtitle=''){const wasOpen=dialog.open;$('#dialog-content').innerHTML=`<div class="modal-head"><div><h2>${esc(title)}</h2>${subtitle?`<p class="subtitle">${esc(subtitle)}</p>`:''}</div><button class="close" data-action="close" aria-label="ปิดหน้าต่าง">×</button></div>${body}${actions}`;if(!wasOpen)dialog.showModal();else dialog.scrollTop=0;}
function formOpen(title,type,fields,options={}){openModal(title,`<form data-form="${type}" ${options.id?`data-id="${esc(options.id)}"`:''}><div class="modal-body"><div class="error" role="alert"></div>${options.intro||''}<div class="form-grid">${fields}<label class="field wide">ผู้บันทึก<input name="operator" ${cloud.enabled?'readonly':''} required maxlength="80" value="${esc(state.operator)}" placeholder="ชื่อของคุณ"></label></div>${options.note?`<p class="form-note">${options.note}</p>`:''}</div><div class="modal-actions"><button type="button" class="secondary" data-action="${options.back?'profile':'close'}" ${options.back?`data-id="${esc(options.back)}"`:''}>ยกเลิก</button><button type="submit" class="primary">${options.submit||'บันทึก'}</button></div></form>`);}
const input=(label,name,value='',type='text',attrs='',wide=false)=>`<label class="field ${wide?'wide':''}">${label}<input type="${type}" name="${name}" value="${esc(value)}" ${attrs}></label>`;
const select=(label,name,values,value='',required=true,wide=false)=>`<label class="field ${wide?'wide':''}">${label}<select name="${name}" ${required?'required':''}>${values.map(v=>`<option value="${esc(v)}" ${v===value?'selected':''}>${esc(v)||'เลือกผลตรวจ'}</option>`).join('')}</select></label>`;
const textarea=(label,name,value='',required=false)=>`<label class="field wide">${label}<textarea name="${name}" ${required?'required':''} maxlength="4000">${esc(value)}</textarea></label>`;
function kennelOptions(value='D1-A01'){return select('กรงที่อยู่','kennel',Care.kennels,value);}
function addAnimal(kennel){const initial=kennel||(view==='map'&&SitePlan.level!=='overview'?`D${SitePlan.selectedBuilding}-A01`:'D1-A01');formOpen('เพิ่มสัตว์ในศูนย์','animal',input('ชื่อ *','name','','text','required maxlength="100"')+input('รหัสสัตว์ (ถ้ามี)','id','','text','maxlength="60"')+input('พันธุ์','breed','','text','maxlength="100"')+select('เพศ','sex',['ไม่ระบุ','Female','Male'])+input('วันเกิด (ค.ศ.)','birth','','date',`max="${Care.bangkokDate()}"`)+select('ช่วงวัยตามทะเบียน','stage',['ไม่ระบุ','Puppy','Adult','Senior'],'ไม่ระบุ')+kennelOptions(initial)+select('สถานะสุขภาพ','status',statuses,'ยังไม่ประเมิน'),{note:'กรอกชื่อเพื่อเพิ่มสัตว์ได้เลย • ไม่ทราบรหัสสามารถเว้นว่าง ระบบจะสร้างรหัสอ้างอิงให้ • วันเกิดไม่ทราบสามารถเว้นว่างได้ • อายุคำนวณอัตโนมัติ'});}
function editAnimalForm(id){
 const a=findAnimal(id);if(!a){toast('ไม่พบสัตว์ที่ต้องการแก้ไข');return;}
 const sexOptions=[...new Set(['ไม่ระบุ','Female','Male',a.sex].filter(Boolean))],stageOptions=[...new Set(['ไม่ระบุ','Puppy','Adult','Senior',a.stage].filter(Boolean))];
 formOpen('แก้ไขประวัติ · '+a.name,'edit-animal',input('ชื่อ *','name',a.name,'text','required maxlength="100"')+input('รหัสสัตว์ (ถ้ามี)','registrationCode',Care.animalCode(a),'text','maxlength="60"')+input('พันธุ์','breed',a.breed||'','text','maxlength="100"')+select('เพศ','sex',sexOptions,a.sex||'ไม่ระบุ')+input('วันเกิด (ค.ศ.)','birth',a.birth||'','date',`max="${Care.bangkokDate()}"`)+select('ช่วงวัยตามทะเบียน','stage',stageOptions,a.stage||'ไม่ระบุ'),{id,back:id,note:'บังคับเฉพาะชื่อ • อายุคำนวณจากวันเกิด • ยา ผลตรวจ งาน และประวัติเดิมจะคงอยู่ครบ'});
}
function openKennel(code){const as=occupants(code);openModal(code,`<div class="modal-body"><p class="subtitle" style="margin-bottom:16px">${as.length} ตัวในกรงนี้ · เพิ่มสัตว์ได้มากกว่าหนึ่งตัว</p><div class="list">${as.map(a=>`<div class="kennel-animal-entry">${animalRow(a)}<button class="secondary full" data-action="monthly-check" data-id="${esc(a.id)}" data-month="${currentMonth()}">บันทึกปัญหาขน เล็บ หู · ${esc(a.name)}</button></div>`).join('')||'<div class="empty-state"><h3>กรงนี้ยังว่าง</h3>เพิ่มสัตว์ใหม่ หรือย้ายสัตว์จากหน้าประวัติ</div>'}</div></div>`,`<div class="modal-actions">${addButton(code)}</div>`);}
function profile(id){const a=findAnimal(id);if(!a)return;const c=latestCheck(a,currentMonth());const active=a.medications.filter(m=>m.active);openModal('ประวัติสัตว์',`<div class="modal-body">${a.placementExample?'<div class="notice">Sunny เป็นข้อมูลตัวอย่างจากทะเบียน ตำแหน่ง D1-A01 ใช้สาธิต ยังไม่ยืนยันคอกจริง</div>':''}<div class="profile-top"><div class="avatar large">${esc(a.name.slice(0,1))}</div><div><h2>${esc(a.name)}</h2><div class="animal-id">${esc(Care.animalCode(a)||'ไม่ระบุรหัส')} · ${esc(a.breed||'ไม่ระบุพันธุ์')}</div><div class="profile-meta">${tag(a.stage||'ไม่ระบุ','neutral')}${tag(a.status,healthClass(a.status))}</div></div></div><div class="profile-details"><div><div class="detail-label">คอกปัจจุบัน</div><div class="detail-value">${esc(a.kennel)}</div></div><div><div class="detail-label">เพศ</div><div class="detail-value">${esc(a.sex)}</div></div><div><div class="detail-label">วันเกิด</div><div class="detail-value">${thaiDate(a.birth)}</div></div><div style="grid-column:1/-1"><div class="detail-label">อายุ ณ วันนี้</div><div class="detail-value">${Care.age(a.birth)}</div></div></div><div class="profile-buttons"><button class="secondary edit-profile-button" data-action="edit-animal" data-id="${esc(id)}">แก้ไขประวัติ</button><button class="secondary" data-action="move" data-id="${esc(id)}">ย้ายคอก</button><button class="primary" data-action="health" data-id="${esc(id)}">อัปเดตสุขภาพ</button></div><div class="profile-section"><div class="section-title"><h3>อาการที่ต้องสังเกต</h3><button class="text-link" data-action="add-note" data-id="${esc(id)}">＋ บันทึกข้อสังเกต</button></div><div class="profile-box">${esc(a.symptoms||'ยังไม่ได้ระบุอาการที่ต้องติดตาม')}</div></div><div class="profile-section"><div class="section-title"><h3>รายการยาที่บันทึกว่ายังใช้อยู่</h3><button class="text-link" data-action="add-med" data-id="${esc(id)}">＋ เพิ่มยา</button></div>${active.map(m=>`<div class="med-item"><div class="med-title"><strong>${esc(m.name)}</strong><button class="text-link danger-text" data-action="stop-med" data-id="${esc(id)}" data-med="${esc(m.id)}">บันทึกหยุดใช้</button></div><div>${esc(m.dose)} · ${esc(m.frequency)}</div>${m.instructions?`<div>${esc(m.instructions)}</div>`:''}<small>เริ่ม ${thaiDate(m.start)}${m.end?' · สิ้นสุดตามแผน '+thaiDate(m.end):''} · ${esc(m.operator)}</small></div>`).join('')||'<p class="side-copy">ยังไม่มีรายการยา ไม่ได้หมายความว่ายืนยันว่าไม่มียา</p>'}${a.medications.some(m=>!m.active)?`<details><summary class="side-copy">ประวัติยาที่หยุดใช้ (${a.medications.filter(m=>!m.active).length})</summary>${a.medications.filter(m=>!m.active).map(m=>`<div class="med-item">${esc(m.name)}<br><small>หยุดใช้ ${thaiDate(m.stoppedAt,true)} · ${esc(m.stoppedBy)}</small></div>`).join('')}</details>`:''}</div><div class="profile-section"><div class="section-title"><h3>ขน · เล็บ · หู</h3><button class="text-link" data-action="monthly-check" data-id="${esc(id)}" data-month="${currentMonth()}">บันทึกปัญหา / ติดตาม →</button></div><div class="profile-box">${c?`${esc(thaiMonth(c.month))}<br>ขน: ${esc(c.coat)} · เล็บ: ${esc(c.nails)} · หู: ${esc(c.ears)}<br>${esc(c.note||'')}<br><small>${esc(c.operator)} · ${thaiDate(c.time,true)}</small>`:'ยังไม่มีบันทึกปัญหาเดือน '+esc(thaiMonth(currentMonth()))+' — ไม่ได้หมายถึงตรวจแล้วหรือปกติ'}</div>${a.checks.length?`<details style="margin-top:10px"><summary class="side-copy">ผลตรวจย้อนหลัง (${a.checks.length} บันทึก)</summary>${[...a.checks].reverse().map(x=>`<div class="med-item"><strong>${esc(thaiMonth(x.month))}</strong><div>ขน: ${esc(x.coat)} · เล็บ: ${esc(x.nails)} · หู: ${esc(x.ears)}</div><div>${esc(x.note)}</div><small>${esc(x.operator)} · ${thaiDate(x.time,true)}</small></div>`).join('')}</details>`:''}</div><div class="profile-section"><div class="section-title"><h3>งานของ ${esc(a.name)}</h3><button class="text-link" data-action="add-task" data-id="${esc(id)}">＋ เพิ่มงาน</button></div>${state.tasks.filter(t=>t.animalId===id&&!t.done).map(t=>`<div class="med-item">${esc(t.title)}<br><small>${thaiDate(t.due)} · ${esc(t.assignee||'ยังไม่มอบหมาย')}</small></div>`).join('')||'<p class="side-copy">ไม่มีงานค้างที่บันทึกไว้</p>'}</div><div class="profile-section"><h3>ข้อสังเกตล่าสุด</h3>${[...a.notes].reverse().slice(0,10).map(n=>`<div class="med-item">${esc(n.text)}<br><small>${esc(n.operator)} · ${thaiDate(n.time,true)}</small></div>`).join('')||'<p class="side-copy">ยังไม่มีบันทึกข้อสังเกต</p>'}</div></div>`);}
function moveForm(id){const a=findAnimal(id);formOpen('ย้ายคอก · '+a.name,'move',kennelOptions(a.kennel)+textarea('เหตุผล / หมายเหตุ','note'),{id,back:id,note:`คอกปัจจุบัน ${esc(a.kennel)} • ข้อมูลและประวัติจะติดตามตัวสัตว์ไปคอกใหม่`});}
function healthForm(id){const a=findAnimal(id);formOpen('อัปเดตสุขภาพ · '+a.name,'health',select('สถานะสุขภาพ','status',statuses,a.status,true,true)+textarea('อาการที่ต้องสังเกตต่อ','symptoms',a.symptoms),{id,back:id,note:'บันทึกข้อสังเกตตามข้อมูลที่มี ระบบไม่วินิจฉัยหรือแนะนำการรักษา'});}
function medForm(id){formOpen('เพิ่มรายการยา · '+findAnimal(id).name,'med',input('ชื่อยา *','name','','text','required maxlength="160"',true)+input('ขนาดและหน่วยตามรายการ *','dose','','text','required maxlength="120"')+input('ความถี่ / เวลาตามรายการ *','frequency','','text','required maxlength="200"')+input('วันเริ่ม *','start',Care.bangkokDate(),'date','required')+input('วันสิ้นสุดตามแผน (ถ้ามี)','end','','date')+textarea('วิธีให้ยา / คำสั่งเพิ่มเติม','instructions'),{id,back:id,note:'คัดลอกตามรายการที่ได้รับ ไม่คำนวณขนาดยาอัตโนมัติ • การเพิ่มรายการนี้ยังไม่ใช่บันทึกว่าได้ให้ยาแล้ว'});}
function checkForm(id,month){const a=findAnimal(id),c=latestCheck(a,month);formOpen('บันทึกปัญหาขน เล็บ หู · '+a.name,'check',input('เดือนที่ตรวจ *','month',month,'month',`required max="${currentMonth()}"`,true)+select('สภาพขน *','coat',['','ปกติ','พันกัน / ต้องแปรง','สกปรก / ต้องทำความสะอาด','มีข้อสังเกตอื่น'],c?.coat||'ปกติ',true,true)+select('ความยาวเล็บ *','nails',['','เหมาะสม','ยาว / ต้องตัด','มีข้อสังเกตอื่น'],c?.nails||'เหมาะสม',true,true)+select('ความสะอาดหู *','ears',['','สะอาด','ต้องทำความสะอาด','มีข้อสังเกตอื่น'],c?.ears||'สะอาด',true,true)+textarea('รายละเอียดและสิ่งที่ต้องทำต่อ','note',c?.note||''),{id,back:id,intro:`<div class="notice">เปลี่ยนเฉพาะหัวข้อที่พบปัญหา แล้วกดบันทึก ข้อมูลจะถูกบันทึกเฉพาะสัตว์ตัวนี้${Care.hasMonthlyIssue(c)?' • ถ้าแก้ไขแล้ว ให้เลือกปกติ / เหมาะสม / สะอาด เพื่อปิดรายการติดตาม โดยประวัติเดิมยังอยู่':''}</div>`,note:'ผลตรวจไม่สร้างงานให้อัตโนมัติ หากต้องทำต่อให้เพิ่มใน “งานดูแล”'});}
function taskForm(id){if(!state.animals.length){toast('เพิ่มสัตว์ก่อนสร้างงาน');return;}formOpen('เพิ่มงานดูแล','task',`<label class="field wide">สัตว์ *<select name="animalId" required>${state.animals.map(a=>`<option value="${esc(a.id)}" ${a.id===id?'selected':''}>${esc(a.name)} · ${esc(Care.animalCode(a)||'ไม่ระบุรหัส')}</option>`).join('')}</select></label>`+input('สิ่งที่ต้องทำ *','title','','text','required maxlength="300"',true)+input('วันที่ต้องทำ *','due',Care.bangkokDate(),'date','required')+input('ผู้รับผิดชอบ','assignee','','text','maxlength="80"'),{back:id,note:'หากมีเวลาเฉพาะ เช่น 08:00 ให้ใส่ในข้อความสิ่งที่ต้องทำ'});}
document.addEventListener('click',e=>{const el=e.target.closest('[data-action]');if(!el)return;const {action,id,code,kennel,month,med}=el.dataset;
 const actions={close:()=>{if(cloud.busy&&$('#admin-reset-form'))return;dialog.close();},'add-animal':()=>addAnimal(kennel),kennel:()=>openKennel(code),profile:()=>profile(id),'edit-animal':()=>editAnimalForm(id),move:()=>moveForm(id),health:()=>healthForm(id),'add-med':()=>medForm(id),'monthly-check':()=>checkForm(id,month),'add-task':()=>taskForm(id),'add-note':()=>formOpen('บันทึกข้อสังเกต · '+findAnimal(id).name,'note',textarea('ข้อสังเกต *','text','',true),{id,back:id}),'stop-med':()=>formOpen('บันทึกหยุดใช้ยา','stop-med',input('รายการยา','med',med,'hidden')+textarea('เหตุผล / หมายเหตุ','reason','',true),{id,back:id,intro:`<div class="notice">บันทึกเฉพาะการหยุดใช้ที่ได้รับแจ้งแล้ว ระบบจะเก็บประวัติรายการยาไว้</div>`}),'toggle-task':()=>{const t=state.tasks.find(t=>t.id===id);formOpen(t.done?'เปิดงานอีกครั้ง':'ยืนยันทำงานเสร็จ','toggle-task','',{id,intro:`<div class="profile-box" style="margin-bottom:18px">${esc(t.title)}<br>${esc(findAnimal(t.animalId)?.name||t.animalId)}</div>`});}};
 actions[action]?.();
});
document.addEventListener('submit',async e=>{const form=e.target.closest('form[data-form]');if(!form)return;e.preventDefault();if(!form.reportValidity())return;const values=Object.fromEntries(new FormData(form));const data=Object.fromEntries(Object.entries(values).map(([k,v])=>[k,typeof v==='string'?v.trim():v]));const type=form.dataset.form,id=form.dataset.id;
 const submit=form.querySelector('[type=submit]');if(submit?.disabled)return;if(submit)submit.disabled=true;
 try{if(cloud.enabled)data.operator=cloud.member.name;if(!data.operator)throw Error('กรุณาระบุชื่อผู้บันทึก');const d=structuredClone(state);d.operator=data.operator;const a=d.animals.find(x=>x.id===id);const time=new Date().toISOString();let resultId=id,msg='บันทึกเรียบร้อย';
 if(type==='animal'){const created=Care.createAnimal(data,d.animals);d.animals.push(created);resultId=created.id;addEvent(d,`เพิ่ม ${created.name} (${created.id}) เข้าคอก ${created.kennel}`,data.operator);}
 else if(type==='edit-animal'){const changes=Care.updateAnimalProfile(a,data,d.animals);if(!changes.length){profile(id);toast('ไม่มีข้อมูลที่เปลี่ยนแปลง');return;}addEvent(d,`แก้ไขประวัติ ${a.name}: ${changes.map(c=>`${c.field} ${c.before||'ไม่ระบุ'} → ${c.after||'ไม่ระบุ'}`).join(' · ')}`,data.operator);msg='แก้ไขประวัติเรียบร้อย';}
 else if(type==='move'){const from=Care.moveAnimal(a,data.kennel);addEvent(d,`ย้าย ${a.name} จาก ${from} ไป ${a.kennel}${data.note?' · '+data.note:''}`,data.operator);msg='ย้ายคอกเรียบร้อย ประวัติยังอยู่ครบ';}
 else if(type==='health'){if(!statuses.includes(data.status))throw Error('กรุณาเลือกสถานะ');a.status=data.status;a.symptoms=data.symptoms;addEvent(d,`อัปเดตสุขภาพ ${a.name}: ${a.status} · อาการที่ต้องสังเกต: ${a.symptoms||'ไม่ได้ระบุ'}`,data.operator);}
 else if(type==='note'){if(!data.text)throw Error('กรุณากรอกข้อสังเกต');a.notes.push({text:data.text,time,operator:data.operator});addEvent(d,`ข้อสังเกต ${a.name}: ${data.text}`,data.operator);}
 else if(type==='med'){if(!data.name||!data.dose||!data.frequency)throw Error('กรุณากรอกข้อมูลยาให้ครบ');if(data.end&&data.end<data.start)throw Error('วันสิ้นสุดต้องไม่ก่อนวันเริ่ม');a.medications.push({id:crypto.randomUUID(),name:data.name,dose:data.dose,frequency:data.frequency,start:data.start,end:data.end,instructions:data.instructions,active:true,operator:data.operator,time});addEvent(d,`เพิ่มรายการยา ${data.name} ของ ${a.name}`,data.operator);}
 else if(type==='stop-med'){const m=a.medications.find(m=>m.id===data.med);if(!m||!m.active)throw Error('รายการยานี้หยุดใช้แล้ว');if(!data.reason)throw Error('กรุณาระบุหมายเหตุ');m.active=false;m.stoppedAt=time;m.stoppedBy=data.operator;m.stopReason=data.reason;addEvent(d,`บันทึกหยุดใช้ ${m.name} ของ ${a.name} · ${data.reason}`,data.operator);}
 else if(type==='check'){if(!data.coat||!data.nails||!data.ears)throw Error('กรุณาตรวจให้ครบทั้งขน เล็บ และหู');if(!/^\d{4}-\d{2}$/.test(data.month)||data.month>currentMonth())throw Error('เดือนไม่ถูกต้องหรือเป็นเดือนในอนาคต');Care.addMonthlyCheck(a,data,{operator:data.operator,time,maxMonth:currentMonth()});addEvent(d,`ตรวจรายเดือน ${a.name} (${thaiMonth(data.month)}): ขน ${data.coat}, เล็บ ${data.nails}, หู ${data.ears}${data.note?' · '+data.note:''}`,data.operator);}
 else if(type==='task'){if(!data.title||!findAnimal(data.animalId))throw Error('กรุณาระบุสัตว์และสิ่งที่ต้องทำ');d.tasks.push({id:crypto.randomUUID(),animalId:data.animalId,title:data.title,due:data.due,assignee:data.assignee,done:false,createdBy:data.operator,time});resultId=data.animalId;addEvent(d,`เพิ่มงานของ ${findAnimal(data.animalId).name}: ${data.title}`,data.operator);}
 else if(type==='toggle-task'){const t=d.tasks.find(t=>t.id===id);if(!t)throw Error('ไม่พบงานนี้');t.done=!t.done;t.completedAt=t.done?time:null;t.completedBy=t.done?data.operator:null;addEvent(d,`${t.done?'ทำงานเสร็จ':'เปิดงานอีกครั้ง'}: ${t.title}`,data.operator);resultId=null;}
 else if(type==='operator'){d.operator=data.operator;resultId=null;}
 else throw Error('ไม่พบแบบฟอร์ม');
 await commit(d);if(resultId)profile(resultId);else dialog.close();toast(msg);
 }catch(err){const box=form.querySelector('.error');if(box){box.textContent=err.message;box.scrollIntoView({block:'nearest'});}else toast(err.message);}
 finally{if(submit)submit.disabled=false;}
});
document.addEventListener('input',e=>{if(e.target.id==='animal-search'){query=e.target.value;const start=e.target.selectionStart;render();$('#animal-search').focus();$('#animal-search').setSelectionRange(start,start);}});
document.addEventListener('change',e=>{if(e.target.id==='status-filter'){statusFilter=e.target.value;render();}if(e.target.id==='check-month'){if(e.target.value&&e.target.value<=currentMonth()){selectedMonth=e.target.value;render();}else{e.target.value=selectedMonth;toast('เลือกเดือนไม่เกินเดือนปัจจุบัน');}}});
$('#operator').addEventListener('click',()=>{if(cloud.enabled){openCloudAccount();return;}formOpen('ชื่อผู้บันทึก','operator','',{note:'ชื่อนี้ยังไม่ใช่การเข้าสู่ระบบ'});});
$('#export').addEventListener('click',()=>{const blob=new Blob([JSON.stringify({exportedAt:new Date().toISOString(),...state},null,2)],{type:'application/json'}),url=URL.createObjectURL(blob),a=document.createElement('a');a.href=url;a.download=`nutrix-care-${Care.bangkokDate()}.json`;a.click();setTimeout(()=>URL.revokeObjectURL(url),1000);toast('ส่งออกข้อมูลในเครื่องนี้แล้ว');});
$('#export-excel').addEventListener('click',async()=>{
 const button=$('#export-excel');if(button.disabled)return;
 if(cloud.enabled&&!cloud.ready){toast('กรุณาเข้าสู่ระบบก่อนส่งออกรายงาน');return;}
 if(cloud.busy){toast('รอให้บันทึกเสร็จก่อนส่งออกรายงาน');return;}
 if(dialog.open){toast('ปิดหน้าต่างที่กำลังกรอกก่อนส่งออกรายงาน');return;}
 button.disabled=true;button.textContent='กำลังส่งออก…';
 try{
  if(cloud.enabled)await cloud.read(true);
  if(cloud.enabled&&!cloud.ready)throw Error('กรุณาเข้าสู่ระบบอีกครั้ง');
  const snapshot=structuredClone(state),now=new Date();
  const bytes=CareReport.build(snapshot,{now,revision:cloud.enabled?cloud.revision:null,source:cloud.enabled?'ฐานข้อมูลกลาง Supabase':'ข้อมูลในเบราว์เซอร์เครื่องนี้',operator:cloud.enabled?cloud.member.name:state.operator});
  const blob=new Blob([bytes],{type:'application/vnd.openxmlformats-officedocument.spreadsheetml.sheet'}),url=URL.createObjectURL(blob),link=document.createElement('a');
  link.href=url;link.download=`nutrix-care-report-${Care.bangkokDate(now)}.xlsx`;document.body.appendChild(link);link.click();link.remove();setTimeout(()=>URL.revokeObjectURL(url),10000);toast('ส่งออกรายงาน Excel แล้ว');
 }catch(err){toast('ส่งออกไม่ได้: '+(cloud.enabled?cloud.message(err):err.message));}
 finally{button.disabled=false;button.textContent='รายงาน Excel';}
});
window.addEventListener('hashchange',()=>{view=navs.some(n=>n[0]===location.hash.slice(1))?location.hash.slice(1):'map';if(dialog.open)dialog.close();render();window.scrollTo(0,0);});
window.addEventListener('storage',e=>{if(!cloud.enabled&&e.key===KEY&&e.newValue){try{const next=JSON.parse(e.newValue);if(next.version===1&&Array.isArray(next.animals)&&Array.isArray(next.tasks)&&Array.isArray(next.events)){state=next;render();if(dialog.open)dialog.close();toast('ข้อมูลอัปเดตจากแท็บอื่นในเบราว์เซอร์นี้');}}catch{toast('ไม่สามารถอ่านการอัปเดตจากแท็บอื่นได้');}}});
dialog.addEventListener('click',e=>{if(cloud.busy&&$('#admin-reset-form'))return;if(e.target===dialog){const r=dialog.getBoundingClientRect();if(e.clientX<r.left||e.clientX>r.right||e.clientY<r.top||e.clientY>r.bottom)dialog.close();}});
view=navs.some(n=>n[0]===location.hash.slice(1))?location.hash.slice(1):'map';render();


function renderCloudLogin(){
 $('#desktop-nav').innerHTML='';$('#mobile-nav').innerHTML='';$('#page-name').textContent='เข้าสู่ระบบ';$('#operator-label').textContent='เข้าสู่ระบบ';
 $('#main').innerHTML=`<section class="card panel-pad cloud-login"><h1>Nutrix Care</h1><p class="subtitle">เข้าสู่ระบบเพื่อใช้ข้อมูลร่วมกันในศูนย์</p><form id="cloud-login"><div class="error" role="alert">${esc(cloud.error)}</div><label class="field">อีเมล<input name="email" type="email" autocomplete="username" required></label><label class="field">รหัสผ่าน<input name="password" type="password" autocomplete="current-password" required></label><label class="remember-login"><input name="remember" type="checkbox" ${cloud.remember?'checked':''}><span>ล็อกอินค้างไว้</span></label><button class="primary full" type="submit">เข้าสู่ระบบ</button></form><p class="side-copy">ใช้บัญชีที่ผู้ดูแลสร้างให้ หากยังไม่มีบัญชีหรือจำรหัสผ่านไม่ได้ กรุณาติดต่อผู้ดูแล</p><button class="text-link" id="export-legacy">ส่งออกข้อมูลเดิมในเครื่องนี้</button></section>`;
}
function cloudStatus(){
 if(!cloud.enabled)return;
 const banner=document.querySelector('.prototype');banner.innerHTML=`<span class="pill">ฐานข้อมูลกลาง</span><span>${cloud.busy?'กำลังบันทึก…':cloud.error?esc(cloud.error):cloud.ready?'เชื่อมต่อแล้ว · ตรวจข้อมูลใหม่ทุก 10 วินาที':'กรุณาเข้าสู่ระบบ'}</span>${cloud.ready?'<button class="text-link" data-cloud="refresh">อัปเดตข้อมูล</button>':''}`;
 if(!cloud.ready)renderCloudLogin();
}
function downloadState(data,prefix){const blob=new Blob([JSON.stringify({exportedAt:new Date().toISOString(),...data},null,2)],{type:'application/json'}),url=URL.createObjectURL(blob),a=document.createElement('a');a.href=url;a.download=prefix+'-'+Care.bangkokDate()+'.json';a.click();setTimeout(()=>URL.revokeObjectURL(url),1000);}
function exportLegacy(){try{const raw=localStorage.getItem(KEY);if(!raw){toast('ไม่มีข้อมูลเดิมในเบราว์เซอร์นี้');return;}downloadState(JSON.parse(raw),'nutrix-care-local-backup');}catch{toast('อ่านข้อมูลเดิมไม่ได้');}}
function openCloudAccount(){if(!cloud.ready)return;openModal('บัญชีผู้ใช้งาน',`<div class="modal-body"><p>${esc(cloud.member.name)} · ${esc(cloud.member.email)}</p><p class="side-copy">ข้อมูลบันทึกลงฐานข้อมูลกลาง ไม่เขียนทับข้อมูลต้นแบบเดิมในเครื่องนี้</p>${cloud.member.role==='admin'?'<label class="field">นำเข้าข้อมูล JSON เดิม (ใช้ได้เมื่อฐานข้อมูลยังว่าง)<input type="file" id="cloud-import" accept=".json,application/json"></label><p class="side-copy">ไม่ย้ายข้อมูลอัตโนมัติ กรุณาตรวจข้อมูลตัวอย่างและรหัสกรงก่อนนำเข้า</p>':''}<div id="import-preview"></div><div class="error" id="cloud-account-error" role="alert"></div><button class="secondary" data-cloud="logout">ออกจากระบบ</button>${cloud.canReset()?'<div class="profile-section"><h3>จัดการข้อมูล</h3><p class="side-copy">เฉพาะผู้ดูแลเจ้าของระบบ ต้องยืนยันบัญชีและรหัสผ่านทุกครั้ง</p><button class="secondary danger-text" data-cloud="reset-open">ล้างข้อมูลทั้งหมด</button></div>':''}</div>`);}
function openResetForm(){
 if(!cloud.canReset())return;
 openModal('ล้างข้อมูลทั้งหมด',`<form id="admin-reset-form"><div class="modal-body"><div class="notice">ล้างทะเบียนสัตว์ ยา ผลตรวจรายเดือน ข้อสังเกต งาน ประวัติกิจกรรม และสำเนาประวัติในฐานข้อมูลทั้งหมด การล้างมีผลกับทุกเครื่องและย้อนกลับจากปุ่มนี้ไม่ได้</div><p class="side-copy">บัญชีผู้ใช้และผังคอกยังคงอยู่ ไฟล์สำรองที่เคยดาวน์โหลดหรือเก็บไว้ใน OneDrive จะยังอยู่</p><p>ขณะนี้มีสัตว์ ${state.animals.length} ตัว · งาน ${state.tasks.length} รายการ</p><div class="error" role="alert"></div><div class="form-grid">${input('อีเมลบัญชีของคุณ *','email',cloud.member.email,'email','required autocomplete="username"',true)}${input('รหัสผ่านเดิมของบัญชี *','password','','password','required autocomplete="current-password"',true)}${input('พิมพ์ “ล้างข้อมูลทั้งหมด” เพื่อยืนยัน *','confirmation','','text','required autocomplete="off"',true)}</div></div><div class="modal-actions"><button type="button" class="secondary" data-action="close">ยกเลิก</button><button type="submit" class="primary admin-reset-submit">ยืนยันล้างข้อมูลทั้งหมด</button></div></form>`);
}
// Erase password fields on close, including Escape/backdrop dismissal.
dialog.addEventListener('close',()=>{const f=document.getElementById('admin-reset-form');if(f)f.reset();});
dialog.addEventListener('cancel',e=>{if(cloud.busy&&$('#admin-reset-form'))e.preventDefault();});
document.addEventListener('submit',async e=>{
 if(e.target.id!=='admin-reset-form')return;e.preventDefault();const form=e.target;if(!form.reportValidity())return;
 const button=form.querySelector('[type="submit"]');if(button.disabled)return;
 const email=form.elements.email.value.trim(),confirmation=form.elements.confirmation.value;
 const error=form.querySelector('.error');error.textContent='';
 if(confirmation!=='ล้างข้อมูลทั้งหมด'){error.textContent='กรุณาพิมพ์ ล้างข้อมูลทั้งหมด ให้ตรงก่อนยืนยัน';return;}
 form.querySelectorAll('button').forEach(b=>b.disabled=true);let password=form.elements.password.value;form.elements.password.value='';
 try{await cloud.resetAll({email,password,confirmation});form.reset();pendingImport=null;dialog.close();render();toast('ล้างข้อมูลสัตว์ งาน และประวัติทั้งหมดเรียบร้อย');}
 catch(err){error.textContent=err.message;}
 finally{password='';form.querySelectorAll('button').forEach(b=>b.disabled=false);}
});
let pendingImport=null;
document.addEventListener('submit',async e=>{if(e.target.id!=='cloud-login')return;e.preventDefault();const form=e.target,button=form.querySelector('button');if(button.disabled)return;button.disabled=true;const values=new FormData(form);try{await cloud.signIn(String(values.get('email')).trim(),String(values.get('password')),values.get('remember')==='on');form.reset();render();cloudStatus();}catch(err){cloud.error=err.message;cloudStatus();}finally{button.disabled=false;}});
document.addEventListener('click',async e=>{
 if(e.target.closest('#export-legacy')){exportLegacy();return;}
 const action=e.target.closest('[data-cloud]')?.dataset.cloud;if(!action)return;
 try{
  if(action==='reset-open'){openResetForm();return;}
  if(action==='logout'){await cloud.signOut();dialog.close();render();}
  if(action==='refresh'){if(dialog.open){toast('ปิดหน้าต่างที่กำลังกรอกก่อนอัปเดตข้อมูล');return;}await cloud.read(true);toast('อัปเดตข้อมูลแล้ว');}
  if(action==='import'&&pendingImport){if(cloud.member.role!=='admin'||state.animals.length||state.tasks.length||state.events.length)throw Error('นำเข้าได้เฉพาะผู้ดูแลและฐานข้อมูลว่าง');await commit(pendingImport);pendingImport=null;dialog.close();toast('นำเข้าฐานข้อมูลกลางสำเร็จ');}
 }catch(err){const box=$('#cloud-account-error');if(box)box.textContent=cloud.message(err);else toast(cloud.message(err));}
});
document.addEventListener('change',async e=>{
 if(e.target.id!=='cloud-import')return;pendingImport=null;$('#import-preview').textContent='';
 try{
  if(state.animals.length||state.tasks.length||state.events.length)throw Error('ฐานข้อมูลมีข้อมูลแล้ว จึงไม่อนุญาตให้นำเข้าทับ');
  const file=e.target.files[0];if(!file)return;if(file.size>10000000)throw Error('ไฟล์ใหญ่เกิน 10 MB');
  const d=JSON.parse(await file.text());if(d.version!==1||!Array.isArray(d.animals)||!Array.isArray(d.tasks)||!Array.isArray(d.events))throw Error('รูปแบบไฟล์ไม่ถูกต้อง');
  const ids=[];for(const a of d.animals){Care.validateAnimal(a,ids);if(!['medications','notes','checks'].every(k=>Array.isArray(a[k])))throw Error('ข้อมูลประวัติสัตว์ไม่ครบ');ids.push(a);}
  if(d.animals.some(a=>a.placementExample))throw Error('ยังมีสัตว์ตำแหน่งตัวอย่าง กรุณายืนยันตำแหน่งในต้นแบบโดยย้ายคอกก่อนส่งออกใหม่');
  if(d.tasks.some(t=>!ids.some(a=>a.id===t.animalId)))throw Error('มีงานที่ไม่พบรหัสสัตว์');
  pendingImport={version:1,operator:cloud.member.name,animals:d.animals,tasks:d.tasks,events:d.events};
  $('#import-preview').innerHTML=`<div class="notice">พบสัตว์ ${d.animals.length} ตัว งาน ${d.tasks.length} รายการ ประวัติ ${d.events.length} รายการ</div><button class="primary" data-cloud="import">ยืนยันนำเข้าข้อมูลชุดนี้</button>`;
 }catch(err){$('#cloud-account-error').textContent=err.message;}
});
if(cloud.enabled){cloudStatus();cloud.init({onChange:next=>{if(!next){if(dialog.open)dialog.close();pendingImport=null;}state=next||emptyState();render();},onStatus:cloudStatus,canRefresh:()=>!dialog.open&&!cloud.busy});}
